using System.Data;
using FIXIT.Domain;
using System.Security.Claims;
using FIXIT.API.Contracts;
using FIXIT.Domain.Entities;
using FIXIT.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace FIXIT.API.Controllers;
[ApiController,Route("api/bookings"),Authorize(Roles="Customer")]
public class BookingsController(FIXITDbContext db) : ControllerBase
{
 string UserId=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 [HttpGet] public async Task<IActionResult> List()=>Ok(await db.Bookings.AsNoTracking().Where(b=>b.CustomerId==UserId).OrderByDescending(b=>b.CreatedAt).Select(b=>new{b.Id,b.Reference,b.ProblemDescription,b.ScheduledAt,status=b.Status.ToString(),b.EstimatedTotal,service=b.Service.Name,address=new{b.Address.Street,b.Address.Barangay,b.Address.CityMunicipality,b.Address.Province},technician=b.Technician==null?null:new{b.Technician.FirstName,b.Technician.LastName,b.Technician.PhoneNumber}}).ToListAsync());
 [HttpPost] public async Task<IActionResult> Create(BookingRequest r)
 {
  if(r.ScheduledAt<=DateTimeOffset.UtcNow.AddHours(2)||r.ScheduledAt> DateTimeOffset.UtcNow.AddDays(90))return BadRequest(new{message="Choose a time at least 2 hours from now and within 90 days."});
  var a=await db.Addresses.SingleOrDefaultAsync(x=>x.Id==r.AddressId&&x.CustomerId==UserId);if(a is null)return BadRequest(new{message="Select one of your saved addresses."});
  var svc=await db.Services.SingleOrDefaultAsync(x=>x.Id==r.ServiceId&&x.IsActive);if(svc is null)return BadRequest(new{message="This service is currently unavailable."});
  var area=await db.ServiceAreas.AnyAsync(x=>x.IsActive&&x.CityMunicipality==a.CityMunicipality&&x.Province==a.Province);if(!area)return BadRequest(new{message="FIXIT is not available at this address yet."});
  var booking=new Booking{Reference=$"FX-{DateTime.UtcNow:yyMMdd}-{Guid.NewGuid().ToString("N")[..6].ToUpperInvariant()}",CustomerId=UserId,AddressId=a.Id,ServiceId=svc.Id,ProblemDescription=r.ProblemDescription.Trim(),ScheduledAt=r.ScheduledAt.UtcDateTime,EstimatedTotal=svc.BasePrice,Status=BookingStatus.Pending};
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);
  db.Bookings.Add(booking);db.PriceLines.Add(new PriceLine{Booking=booking,Label=svc.Name,Amount=svc.BasePrice});db.BookingStatusHistories.Add(new BookingStatusHistory{Booking=booking,Status=BookingStatus.Pending,ChangedByUserId=UserId,Note="Booking requested"});
  db.Payments.Add(new Payment{Booking=booking,Method=r.PaymentMethod,Amount=svc.BasePrice,Status=PaymentStatus.Pending});db.Notifications.Add(new(){UserId=UserId,Title="Booking request received",Message=$"Your FIXIT request {booking.Reference} is confirmed as pending."});var local=r.ScheduledAt.UtcDateTime.AddHours(8);var slot=TimeOnly.FromDateTime(local);var recipients=await db.TechnicianProfiles.Where(t=>t.Status==TechnicianStatus.Approved&&t.IsOnline&&db.TechnicianSkills.Any(s=>s.TechnicianId==t.UserId&&s.ServiceId==svc.Id)&&db.TechnicianCoverageAreas.Any(c=>c.TechnicianId==t.UserId&&c.ServiceArea.IsActive&&c.ServiceArea.CityMunicipality==a.CityMunicipality&&c.ServiceArea.Province==a.Province)&&db.TechnicianAvailabilities.Any(v=>v.TechnicianId==t.UserId&&v.IsAvailable&&v.DayOfWeek==(int)local.DayOfWeek&&v.StartTime<=slot&&v.EndTime>=slot)&&!db.Bookings.Any(x=>x.TechnicianId==t.UserId&&x.Status!=BookingStatus.Cancelled&&x.ScheduledAt>=booking.ScheduledAt.AddHours(-2)&&x.ScheduledAt<=booking.ScheduledAt.AddHours(2))).Select(t=>t.UserId).ToListAsync();foreach(var recipient in recipients)db.Notifications.Add(new(){UserId=recipient,Title="New service request in your area",Message=$"A FIXIT request {booking.Reference} may match your coverage and availability."});await db.SaveChangesAsync();await tx.CommitAsync();return Created($"/api/bookings/{booking.Id}",new{id=booking.Id,booking.Reference,booking.Status,booking.EstimatedTotal});
 }
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var b=await db.Bookings.AsNoTracking().Where(x=>x.Id==id&&x.CustomerId==UserId).Select(x=>new{x.Id,x.Reference,x.ProblemDescription,x.ScheduledAt,status=x.Status.ToString(),x.EstimatedTotal,x.CompletionNotes,x.PartsUsed,service=x.Service.Name,address=new{x.Address.Street,x.Address.Barangay,x.Address.CityMunicipality,x.Address.Province,x.Address.Region,x.Address.Landmark},technician=x.Technician==null?null:new{x.Technician.FirstName,x.Technician.LastName,x.Technician.PhoneNumber},history=x.History.OrderBy(h=>h.ChangedAt).Select(h=>new{status=h.Status.ToString(),h.ChangedAt,h.Note}).ToList(),prices=db.PriceLines.Where(p=>p.BookingId==x.Id).Select(p=>new{p.Label,p.Amount}).ToList(),additionalWork=db.AdditionalWorkRequests.Where(w=>w.BookingId==x.Id).Select(w=>new{id=w.Id,w.Description,w.Amount,status=w.Status.ToString()}).ToList(),payment=db.Payments.Where(p=>p.BookingId==x.Id).Select(p=>new{p.Id,p.Amount,status=p.Status.ToString(),method=p.Method.ToString(),p.TransactionReference,p.IsSimulation}).FirstOrDefault()}).FirstOrDefaultAsync();return b is null?NotFound():Ok(b);}
 [HttpPost("{id:int}/cancel")] public async Task<IActionResult> Cancel(int id){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.CustomerId==UserId);if(b is null)return NotFound();var hours=(await db.PlatformSettings.FindAsync("CancellationHours"))?.NumericValue??24m;if(b.Status is not (BookingStatus.Pending or BookingStatus.Accepted)||b.ScheduledAt<DateTime.UtcNow.AddHours((double)hours))return Conflict(new{message=$"This booking is no longer eligible for cancellation. Cancel at least {hours} hours before the appointment."});b.Status=BookingStatus.Cancelled;db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Cancelled by customer"});if(b.TechnicianId is not null)db.Notifications.Add(new(){UserId=b.TechnicianId,Title="Booking cancelled",Message=$"Booking {b.Reference} was cancelled by the customer."});db.Notifications.Add(new(){UserId=UserId,Title="Booking cancelled",Message=$"Your booking {b.Reference} was cancelled."});await db.SaveChangesAsync();return NoContent();}
 [HttpPost("{id:int}/reschedule")] public async Task<IActionResult> Reschedule(int id,[FromBody] DateTimeOffset when){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.CustomerId==UserId);if(b is null)return NotFound();var hours=(await db.PlatformSettings.FindAsync("CancellationHours"))?.NumericValue??24m;if(b.Status is not (BookingStatus.Pending or BookingStatus.Accepted)||b.ScheduledAt<DateTime.UtcNow.AddHours((double)hours)||when<=DateTimeOffset.UtcNow.AddHours(2)||when>DateTimeOffset.UtcNow.AddDays(90))return Conflict(new{message="This booking cannot be rescheduled."});if(b.TechnicianId is not null){var local=when.UtcDateTime.AddHours(8);var slot=TimeOnly.FromDateTime(local);if(!await db.TechnicianAvailabilities.AnyAsync(a=>a.TechnicianId==b.TechnicianId&&a.IsAvailable&&a.DayOfWeek==(int)local.DayOfWeek&&a.StartTime<=slot&&a.EndTime>=slot))return Conflict(new{message="The assigned technician is not available at that time."});if(await db.Bookings.AnyAsync(x=>x.Id!=id&&x.TechnicianId==b.TechnicianId&&x.Status!=BookingStatus.Cancelled&&x.ScheduledAt>=when.UtcDateTime.AddHours(-2)&&x.ScheduledAt<=when.UtcDateTime.AddHours(2)))return Conflict(new{message="The assigned technician is unavailable at that time."});}b.ScheduledAt=when.UtcDateTime;db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Rescheduled by customer"});if(b.TechnicianId is not null)db.Notifications.Add(new(){UserId=b.TechnicianId,Title="Booking rescheduled",Message=$"Booking {b.Reference} was rescheduled to {when.LocalDateTime:g} Philippine time."});db.Notifications.Add(new(){UserId=UserId,Title="Booking rescheduled",Message=$"Your booking {b.Reference} was rescheduled."});await db.SaveChangesAsync();await tx.CommitAsync();return NoContent();}
 [HttpPost("{id:int}/reviews")] public async Task<IActionResult> Review(int id,ReviewRequest r){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.CustomerId==UserId);if(b is null)return NotFound();if(b.Status!=BookingStatus.Completed)return Conflict(new{message="Reviews are available after work is completed."});if(await db.Reviews.AnyAsync(x=>x.BookingId==id))return Conflict(new{message="This booking already has a review."});var review=new Review{BookingId=id,CustomerId=UserId,Rating=r.Rating,Comment=r.Comment?.Trim()};db.Reviews.Add(review);await db.SaveChangesAsync();return Created($"/api/bookings/{id}/reviews",new{review.Id});}
 [HttpPost("{id:int}/confirm-completion")] public async Task<IActionResult> ConfirmCompletion(int id){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.CustomerId==UserId);if(b is null)return NotFound();if(!BookingWorkflow.CanTransition(b.Status,BookingStatus.Completed))return Conflict(new{message="The technician must mark the work complete before you can confirm it."});b.Status=BookingStatus.Completed;db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Customer confirmed completion"});await db.SaveChangesAsync();return Ok(new{status=b.Status.ToString()});}
 [HttpPost("{id:int}/additional-work/{workId:int}")] public async Task<IActionResult> DecideWork(int id,int workId,[FromQuery]bool approve){var w=await db.AdditionalWorkRequests.Include(x=>x.Booking).SingleOrDefaultAsync(x=>x.Id==workId&&x.BookingId==id&&x.Booking.CustomerId==UserId);if(w is null)return NotFound();if(w.Status!=WorkRequestStatus.Pending)return Conflict();if(w.Booking.Status!=BookingStatus.InProgress)return Conflict(new{message="Additional work must be approved before the technician completes the job."});w.Status=approve?WorkRequestStatus.Approved:WorkRequestStatus.Rejected;w.DecidedAt=DateTime.UtcNow;if(approve){w.Booking.EstimatedTotal+=w.Amount;var pay=await db.Payments.SingleAsync(p=>p.BookingId==id);pay.Amount+=w.Amount;db.PriceLines.Add(new(){BookingId=id,Label=w.Description,Amount=w.Amount});}db.Notifications.Add(new(){UserId=w.TechnicianId,Title=approve?"Additional work approved":"Additional work declined",Message=$"Your request for booking {w.Booking.Reference} was {w.Status.ToString().ToLowerInvariant()}."});await db.SaveChangesAsync();return Ok(new{status=w.Status.ToString(),total=w.Booking.EstimatedTotal});}
 [HttpPost("{id:int}/disputes")] public async Task<IActionResult> Dispute(int id,DisputeRequest r){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.CustomerId==UserId);if(b is null)return NotFound();if(b.Status is BookingStatus.Cancelled or BookingStatus.Disputed)return Conflict();b.Status=BookingStatus.Disputed;db.Disputes.Add(new(){BookingId=id,ReportedById=UserId,Description=r.Description.Trim()});db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Customer opened a dispute"});await db.SaveChangesAsync();return Accepted();}
}
